import json
from itertools import permutations

def solve_puzzle():
    houses = [1, 2, 3, 4, 5]  # left to right
    names = ["Eric", "Alice", "Peter", "Bob", "Arnold"]
    children = ["Timothy", "Meredith", "Samantha", "Fred", "Bella"]

    solutions = []

    # Children constraints:
    # - Fred is in the second house (index 1).
    # - Fred is directly left of Bella -> Bella is in third house (index 2).
    fixed_children = [None] * 5
    fixed_children[1] = "Fred"
    fixed_children[2] = "Bella"

    remaining_children = [c for c in children if c not in ("Fred", "Bella")]
    remaining_positions = [0, 3, 4]

    for perm_children in permutations(remaining_children):
        child_arr = fixed_children[:]
        for pos, child in zip(remaining_positions, perm_children):
            child_arr[pos] = child

        # Precompute child positions
        pos_child = {child_arr[i]: i for i in range(5)}

        # Apply constraints involving only children first if any:
        # 2) Timothy's mother is to the left of Samantha's mother
        if not (pos_child["Timothy"] < pos_child["Samantha"]):
            continue

        for name_arr in permutations(names):
            # Apply name-only constraints
            # 5) Eric is not in the third house (index 2)
            if name_arr[2] == "Eric":
                continue
            # 6) Bob is not in the third house (index 2)
            if name_arr[2] == "Bob":
                continue

            # Precompute name positions
            pos_name = {name_arr[i]: i for i in range(5)}

            # 1) Bob is somewhere to the left of the person whose child is Samantha
            if not (pos_name["Bob"] < pos_child["Samantha"]):
                continue

            # 4) There is one house between Alice and the person whose child is Samantha
            if abs(pos_name["Alice"] - pos_child["Samantha"]) != 2:
                continue

            # 8) Samantha is somewhere to the left of Peter
            if not (pos_child["Samantha"] < pos_name["Peter"]):
                continue

            # All constraints satisfied
            solutions.append((name_arr, child_arr))

    # Choose the first solution (expecting uniqueness)
    if not solutions:
        raise ValueError("No solution found")

    name_arr, child_arr = solutions[0]

    result = {
        "solution": {
            "header": ["House", "Name", "Children"],
            "rows": []
        }
    }

    for i in range(5):
        row = [str(i + 1), name_arr[i], child_arr[i]]
        result["solution"]["rows"].append(row)

    return result

if __name__ == "__main__":
    res = solve_puzzle()
    print(json.dumps(res, ensure_ascii=False))
